<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';require_once __DIR__.'/../lib/notifications.php';
send_cors_headers();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){
    $context=require_admin('vendor_applications.view');$id=trim((string)($_GET['id']??''));
    if($id!==''){$stmt=get_db()->prepare('SELECT a.*,v.vendor_type,v.owner_name,v.display_name,v.email,v.mobile,v.status AS vendor_status,v.verification_status,v.onboarding_status FROM vendor_applications a JOIN vendors v ON v.id=a.vendor_id WHERE a.id=:id LIMIT 1');$stmt->execute(['id'=>$id]);$application=$stmt->fetch();if(!$application)json_response(404,['success'=>false,'message'=>'Application not found.']);$sections=get_db()->prepare('SELECT section_code,data_json,is_complete,updated_at FROM vendor_onboarding_sections WHERE application_id=:id');$sections->execute(['id'=>$id]);$documents=get_db()->prepare('SELECT d.id,d.document_type,d.verification_status,d.rejection_reason,d.created_at,f.mime_type,f.size_bytes,f.scan_status FROM vendor_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.application_id=:id AND f.deleted_at IS NULL ORDER BY d.created_at');$documents->execute(['id'=>$id]);json_response(200,['success'=>true,'application'=>$application,'sections'=>$sections->fetchAll(),'documents'=>$documents->fetchAll()]);}
    $status=trim((string)($_GET['status']??''));$type=trim((string)($_GET['vendor_type']??''));$q=trim((string)($_GET['q']??''));$limit=min(100,max(1,(int)($_GET['limit']??25)));$offset=max(0,(int)($_GET['offset']??0));$where=[];$params=[];
    if($status!==''){$where[]='a.status=:status';$params['status']=$status;}if(in_array($type,['brand','artisan'],true)){$where[]='v.vendor_type=:type';$params['type']=$type;}if($q!==''){$where[]='(a.reference LIKE :q OR v.owner_name LIKE :q OR v.display_name LIKE :q OR v.email LIKE :q)';$params['q']='%'.$q.'%';}$sql='SELECT a.id,a.reference,a.status,a.completion_percent,a.submitted_at,a.updated_at,v.id AS vendor_id,v.vendor_type,v.owner_name,v.display_name,v.email FROM vendor_applications a JOIN vendors v ON v.id=a.vendor_id'.($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY COALESCE(a.submitted_at,a.created_at) DESC LIMIT {$limit} OFFSET {$offset}";$stmt=get_db()->prepare($sql);$stmt->execute($params);json_response(200,['success'=>true,'applications'=>$stmt->fetchAll(),'limit'=>$limit,'offset'=>$offset]);
}
if($method!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$action=(string)($body['action']??'');$applicationId=(string)($body['application_id']??'');
if($action==='document_decision'){
    $context=require_admin('vendor_applications.review');$documentId=(string)($body['document_id']??'');$decision=(string)($body['decision']??'');$reason=trim((string)($body['reason']??''));if(!in_array($decision,['verified','rejected'],true))json_response(422,['success'=>false,'message'=>'Choose verified or rejected.']);
    $stmt=get_db()->prepare('SELECT d.*,f.scan_status FROM vendor_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.id=:id AND d.application_id=:application LIMIT 1');$stmt->execute(['id'=>$documentId,'application'=>$applicationId]);$document=$stmt->fetch();if(!$document)json_response(404,['success'=>false,'message'=>'Document not found.']);if($decision==='verified'&&$document['scan_status']!=='clean')json_response(409,['success'=>false,'message'=>'A document cannot be verified until malware scanning reports clean.']);if($decision==='rejected'&&mb_strlen($reason)<10)json_response(422,['success'=>false,'message'=>'Provide a clear rejection reason.']);
    get_db()->prepare('UPDATE vendor_documents SET verification_status=:decision,verified_by=:admin,verified_at=UTC_TIMESTAMP(),rejection_reason=:reason,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['decision'=>$decision,'admin'=>$context['admin']['id'],'reason'=>$decision==='rejected'?$reason:null,'id'=>$documentId]);audit_event('admin.vendor_document_'.$decision,'vendor_document',$documentId,['application_id'=>$applicationId,'reason'=>$decision==='rejected'?$reason:null]);json_response(200,['success'=>true,'message'=>'Document decision saved.']);
}
$permission=in_array($action,['approve','reject','changes_requested'],true)?'vendor_applications.approve':($action==='start_review'?'vendor_applications.review':'vendors.manage');$context=require_admin($permission);$db=get_db();$db->beginTransaction();
try{
    if(in_array($action,['suspend','reactivate'],true)){$vendorId=(string)($body['vendor_id']??'');$stmt=$db->prepare('SELECT * FROM vendors WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$vendorId]);$vendor=$stmt->fetch();if(!$vendor)json_response(404,['success'=>false,'message'=>'Vendor not found.']);$next=$action==='suspend'?'suspended':'active';$reason=trim((string)($body['reason']??''));if($action==='suspend'&&mb_strlen($reason)<10)json_response(422,['success'=>false,'message'=>'Provide a suspension reason.']);$db->prepare('UPDATE vendors SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'id'=>$vendorId]);if($action==='suspend')revoke_principal_sessions('vendor',$vendorId,'vendor_suspended');record_status_change('vendor',$vendorId,$vendor['status'],$next,$reason);create_notification('vendor',$vendorId,'account_'.$next,'Vendor account '.($next==='active'?'reactivated':'suspended'),$reason?:'Your vendor account status was updated.');audit_event('admin.vendor_'.$action,'vendor',$vendorId,['reason'=>$reason]);$db->commit();json_response(200,['success'=>true,'message'=>'Vendor status updated.']);}
    $stmt=$db->prepare('SELECT a.*,v.vendor_type,v.status AS vendor_status FROM vendor_applications a JOIN vendors v ON v.id=a.vendor_id WHERE a.id=:id FOR UPDATE');$stmt->execute(['id'=>$applicationId]);$application=$stmt->fetch();if(!$application)json_response(404,['success'=>false,'message'=>'Application not found.']);$reason=trim((string)($body['reason']??''));$current=$application['status'];
    $map=['submitted'=>['under_review','changes_requested','rejected','approved'],'under_review'=>['changes_requested','rejected','approved'],'changes_requested'=>[],'approved'=>[],'rejected'=>[]];$next=['start_review'=>'under_review','changes_requested'=>'changes_requested','reject'=>'rejected','approve'=>'approved'][$action]??'';if($next==='')json_response(422,['success'=>false,'message'=>'Unsupported review action.']);assert_transition($current,$next,$map);if(in_array($next,['changes_requested','rejected'],true)&&mb_strlen($reason)<10)json_response(422,['success'=>false,'message'=>'Provide a clear reason for this decision.']);
    if($next==='approved'){$sectionStmt=$db->prepare('SELECT COUNT(*) FROM vendor_onboarding_sections WHERE application_id=:id AND is_complete=1');$sectionStmt->execute(['id'=>$applicationId]);if((int)$sectionStmt->fetchColumn()<4)json_response(409,['success'=>false,'message'=>'All onboarding sections must be complete before approval.']);$docStmt=$db->prepare('SELECT COUNT(*) FROM vendor_documents d JOIN file_assets f ON f.id=d.file_asset_id WHERE d.application_id=:id AND (d.verification_status<>"verified" OR f.scan_status<>"clean")');$docStmt->execute(['id'=>$applicationId]);if((int)$docStmt->fetchColumn()>0)json_response(409,['success'=>false,'message'=>'All submitted documents must be clean and verified before approval.']);$db->prepare('UPDATE vendors SET status="active",verification_status="approved",onboarding_status="completed",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$application['vendor_id']]);$db->prepare('UPDATE vendor_store_profiles SET is_public=1 WHERE vendor_id=:id')->execute(['id'=>$application['vendor_id']]);}
    elseif($next==='changes_requested'){$db->prepare('UPDATE vendors SET verification_status="changes_requested",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$application['vendor_id']]);}
    elseif($next==='rejected'){$db->prepare('UPDATE vendors SET verification_status="rejected",status="inactive",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$application['vendor_id']]);revoke_principal_sessions('vendor',$application['vendor_id'],'application_rejected');}
    else{$db->prepare('UPDATE vendors SET verification_status="under_review",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$application['vendor_id']]);}
    $db->prepare('UPDATE vendor_applications SET status=:status,review_started_at=COALESCE(review_started_at,UTC_TIMESTAMP()),reviewed_at=:reviewed,reviewed_by=:admin,decision_reason=:reason,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$next,'reviewed'=>in_array($next,['approved','rejected','changes_requested'],true)?gmdate('Y-m-d H:i:s'):null,'admin'=>$context['admin']['id'],'reason'=>$reason?:null,'id'=>$applicationId]);$db->prepare('INSERT INTO vendor_verifications (application_id,reviewer_id,decision,notes,created_at) VALUES (:application,:reviewer,:decision,:notes,UTC_TIMESTAMP())')->execute(['application'=>$applicationId,'reviewer'=>$context['admin']['id'],'decision'=>$next,'notes'=>$reason?:null]);record_status_change('vendor_application',$applicationId,$current,$next,$reason);create_notification('vendor',$application['vendor_id'],'application_'.$next,'Vendor application '.str_replace('_',' ',$next),$reason?:'Your vendor application status was updated.','../auth/status.php',['reference'=>$application['reference']]);audit_event('admin.vendor_application_'.$next,'vendor_application',$applicationId,['reason'=>$reason?:null]);$db->commit();json_response(200,['success'=>true,'message'=>'Application status updated.','status'=>$next]);
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
